import base64
import os
from typing import Any, Dict, List, Optional

import boto3


def _read_input_document(file_path: Optional[str] = None, document_bytes: Optional[bytes] = None) -> bytes:
    if document_bytes is not None:
        return document_bytes
    if not file_path:
        raise ValueError("Provide either file_path or document_bytes.")
    with open(file_path, "rb") as f:
        return f.read()


def _to_float(value: Any) -> Optional[float]:
    if value is None:
        return None
    if isinstance(value, (int, float)):
        return float(value)
    try:
        cleaned = str(value).strip().replace(",", "")
        if cleaned.startswith("$"):
            cleaned = cleaned[1:]
        return float(cleaned)
    except Exception:
        return None


def _parse_expense_fields(expense_document: Dict[str, Any]) -> Dict[str, Any]:
    summary_fields = expense_document.get("SummaryFields", []) or []
    line_item_groups = expense_document.get("LineItemGroups", []) or []

    vendor = None
    date = None
    total = None
    line_items: List[Dict[str, Any]] = []

    for field in summary_fields:
        field_type = (field.get("Type") or {}).get("Text") or ""
        value_detection = field.get("ValueDetection") or {}
        text = value_detection.get("Text")

        if field_type in {"VENDOR_NAME", "SUPPLIER_NAME", "RECEIVER_NAME"} and vendor is None:
            vendor = text
        elif field_type in {"INVOICE_RECEIPT_DATE", "DATE"} and date is None:
            date = text
        elif field_type in {"TOTAL", "AMOUNT_DUE", "INVOICE_RECEIPT_TOTAL"} and total is None:
            total = _to_float(text) if text is not None else None

    for group in line_item_groups:
        for item in group.get("LineItems", []) or []:
            item_data: Dict[str, Any] = {}
            description = None
            quantity = None
            unit_price = None
            amount = None

            for field in item.get("LineItemExpenseFields", []) or []:
                field_type = (field.get("Type") or {}).get("Text") or ""
                value_detection = field.get("ValueDetection") or {}
                text = value_detection.get("Text")

                if field_type in {"ITEM", "PRODUCT_CODE", "DESCRIPTION"} and description is None:
                    description = text
                elif field_type in {"QUANTITY", "COUNT"} and quantity is None:
                    quantity = _to_float(text)
                elif field_type in {"PRICE", "UNIT_PRICE"} and unit_price is None:
                    unit_price = _to_float(text)
                elif field_type in {"AMOUNT", "TOTAL_PRICE", "EXTENDED_PRICE"} and amount is None:
                    amount = _to_float(text)

            if description is not None:
                item_data["description"] = description
            if quantity is not None:
                item_data["quantity"] = quantity
            if unit_price is not None:
                item_data["unit_price"] = unit_price
            if amount is not None:
                item_data["amount"] = amount

            if item_data:
                line_items.append(item_data)

    return {
        "vendor": vendor,
        "date": date,
        "total": total,
        "line_items": line_items,
    }


def extract_invoice_fields(
    file_path: Optional[str] = None,
    document_bytes: Optional[bytes] = None,
    aws_region: Optional[str] = None,
) -> Dict[str, Any]:
    """
    Extract vendor, date, total, and line-item fields from an invoice using Amazon Textract AnalyzeExpense.
    """
    payload = _read_input_document(file_path=file_path, document_bytes=document_bytes)

    client = boto3.client("textract", region_name=aws_region or os.getenv("AWS_REGION"))
    response = client.analyze_expense(Document={"Bytes": payload})

    expense_documents = response.get("ExpenseDocuments", []) or []
    if not expense_documents:
        return {"vendor": None, "date": None, "total": None, "line_items": []}

    result = _parse_expense_fields(expense_documents[0])
    return result
